	public class SensorSelector
	{
		private static HashSet<int> usedIndexes = new HashSet<int>();

		private static Random rnd = new Random();

		public static string SelectRandomSensorWithoutRepeat(List<string> sensors)
		{
			if (sensors == null || sensors.Count == 0)
			{
				return null;
			}
			if (usedIndexes.Count == sensors.Count)
			{
				usedIndexes.Clear();
			}
			List<int> list = (from i in Enumerable.Range(0, sensors.Count)
				where !usedIndexes.Contains(i)
				select i).ToList();
			int num = list[rnd.Next(list.Count)];
			usedIndexes.Add(num);
			return sensors[num];
		}
	}

