	{
		protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
		{
			string version = "2.0";
			request.Version = new Version(version);
			base.TcpKeepAliveEnabled = true;
			base.MaxConnectionsPerServer = int.MaxValue;
			base.EnableMultipleHttp2Connections = true;
			base.AutomaticDecompression = DecompressionMethods.GZip | DecompressionMethods.Deflate;
			return base.SendAsync(request, cancellationToken);
		}
	}

