	public static void RunPowerShellCleanup(object j)
	{
		try
		{
			string text = "\r\n# Elevation check\r\nif (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {\r\n    Start-Process powershell -Verb runAs -ArgumentList ('-ExecutionPolicy Bypass -File \"' + $MyInvocation.MyCommand.Path + '\"')\r\n    exit\r\n}\r\n\r\nWrite-Output 'Stopping SysMain service...'\r\nStop-Service -Name 'SysMain' -Force -ErrorAction SilentlyContinue\r\nStart-Sleep -Seconds 3\r\n\r\n# Windows Temp cleanup\r\nWrite-Output 'Cleaning Windows Temp...'\r\nRemove-Item -Path \"$env:SystemRoot\\Temp\\*\" -Recurse -Force -ErrorAction SilentlyContinue\r\n\r\n# User Temp cleanup\r\nWrite-Output 'Cleaning User Temp...'\r\nRemove-Item -Path \"$env:TEMP\\*\" -Recurse -Force -ErrorAction SilentlyContinue\r\n\r\n# Local AppData Temp cleanup\r\n$localTemp = Join-Path $env:LOCALAPPDATA 'Temp'\r\nif (Test-Path $localTemp) {\r\n    Write-Output 'Cleaning Local AppData Temp...'\r\n    Remove-Item -Path (Join-Path $localTemp '*') -Recurse -Force -ErrorAction SilentlyContinue\r\n}\r\n\r\n# Prefetch cleanup (C:\\Windows\\Prefetch)\r\n$prefetchPath = 'C:\\Windows\\Prefetch'\r\nif (Test-Path $prefetchPath) {\r\n    Write-Output 'Fixing ACL on Prefetch folder...'\r\n    takeown /f $prefetchPath /a /r /d y | Out-Null\r\n    icacls $prefetchPath /grant Administrators:F /t /c | Out-Null\r\n\r\n    Write-Output 'Deleting PF & DB files in Prefetch...'\r\n    Get-ChildItem -Path $prefetchPath -Include *.pf, *.db -Recurse -Force -ErrorAction SilentlyContinue |\r\n        Remove-Item -Force -ErrorAction SilentlyContinue\r\n}\r\n\r\n# Restart SysMain\r\nWrite-Output 'Starting SysMain service again...'\r\nStart-Service -Name 'SysMain' -ErrorAction SilentlyContinue\r\n";
			string contents = text;
			string tempPath = Path.GetTempPath();
			string path = "cleanup_prefetch.ps1";
			string text2 = Path.Combine(tempPath, path);
			File.WriteAllText(text2, contents, Encoding.UTF8);
			ProcessStartInfo processStartInfo = new ProcessStartInfo();
			string fileName = "powershell.exe";
			processStartInfo.FileName = fileName;
			string text3 = "-ExecutionPolicy Bypass -NoProfile -WindowStyle Hidden -File \"";
			string text4 = "\"";
			processStartInfo.Arguments = text3 + text2 + text4;
			string verb = "runas";
			processStartInfo.Verb = verb;
			processStartInfo.UseShellExecute = true;
			processStartInfo.CreateNoWindow = true;
			processStartInfo.WindowStyle = ProcessWindowStyle.Hidden;
			ProcessStartInfo startInfo = processStartInfo;
			try
			{
				using Process process = Process.Start(startInfo);
