	public static string UpdateFirstTimestamps(string input, string mup)
	{
		string pattern = "\\$(\\d{13})\\|([\\-]?\\d{1,10})\\|";
		Regex regex = new Regex(pattern, RegexOptions.Compiled);
		if (string.IsNullOrEmpty(input))
		{
			return input;
		}
		string input2 = input;
		string pattern2 = "&&&(.*?)&&&";
		input = Regex.Replace(input2, pattern2, delegate
		{
			string text = "&&&";
			string text2 = mup;
			string text3 = "&&&";
			return text + text2 + text3;
		});
		long currentMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
		return regex.Replace(input, delegate(Match match)
		{
			string value = match.Groups[2].Value;
			string format = "${0}|{1}|";
			return string.Format(format, currentMs, value);
		});
	}

	public static List<System.Net.Cookie> GetAllCookies(CookieContainer cookieContainer)
	{
		List<System.Net.Cookie> list = new List<System.Net.Cookie>();
		try
		{
			if (cookieContainer == null)
			{
				return list;
			}
			Type type = cookieContainer.GetType();
			string name = "m_domainTable";
			Hashtable hashtable = (Hashtable)type.InvokeMember(name, BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.GetField, null, cookieContainer, new object[0]);
			foreach (object key in hashtable.Keys)
			{
				object obj = hashtable[key];
				Type type2 = obj.GetType();
				string name2 = "m_list";
				FieldInfo field = type2.GetField(name2, BindingFlags.Instance | BindingFlags.NonPublic);
				if (field == null || !(field.GetValue(obj) is IDictionary dictionary))
				{
					continue;
				}
				foreach (object key2 in dictionary.Keys)
				{
					if (!(dictionary[key2] is CookieCollection cookieCollection))
					{
						continue;
					}
					foreach (System.Net.Cookie item in cookieCollection)
					{
						list.Add(item);
					}
				}
			}
		}
		catch (Exception)
		{
		}
		return list;
	}

