	private string SHA512(string input)
	{
		string hashName = "SHA-512";
		HashAlgorithm hashAlgorithm = HashAlgorithm.Create(hashName);
		byte[] bytes = Encoding.UTF8.GetBytes(input);
		byte[] bArr = hashAlgorithm.ComputeHash(bytes);
		return BytesToHexStr(bArr);
	}

	private string BytesToHexStr(byte[] bArr)
	{
		if (bArr == null)
		{
			return null;
		}
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < bArr.Length; i++)
		{
			string format = "{0:x2}";
			stringBuilder.Append(string.Format(format, bArr[i]));
		}
		return stringBuilder.ToString();
	}

