	public static RijndaelManaged GetRijndaelManaged(byte[] secretKeyBytes)
	{
		byte[] array = new byte[16];
		Array.Copy(secretKeyBytes, array, 16);
		return new RijndaelManaged
		{
			Mode = CipherMode.CBC,
			Padding = PaddingMode.PKCS7,
			KeySize = 128,
			BlockSize = 128,
			Key = secretKeyBytes,
			IV = array
		};
	}

	public static string Base64Encode(byte[] plainData)
	{
		return Convert.ToBase64String(plainData);
	}

	public static string encrypt(string str, string substring)
	{
		byte[] bytes = Encoding.UTF8.GetBytes(str);
		return Base64Encode(GetRijndaelManaged(Encoding.UTF8.GetBytes(substring)).CreateEncryptor().TransformFinalBlock(bytes, 0, bytes.Length));
	}

	public static string decrypt(string encryptedStr, string substring)
	{
		byte[] array = Convert.FromBase64String(encryptedStr);
		byte[] bytes = GetRijndaelManaged(Encoding.UTF8.GetBytes(substring)).CreateDecryptor().TransformFinalBlock(array, 0, array.Length);
		return Encoding.UTF8.GetString(bytes);
	}

	public static string Decrypt(string key, string ciphertext)
	{
		string text = "encdec: decrypt ";
		string text2 = " -&- ";
		Console.WriteLine(text + key + text2 + ciphertext);
		byte[] bytes = Encoding.UTF8.GetBytes(key);
		byte[] iV = bytes;
		using Aes aes = Aes.Create();
		aes.Key = bytes;
		aes.IV = iV;
		ICryptoTransform transform = aes.CreateDecryptor(aes.Key, aes.IV);
		using MemoryStream stream = new MemoryStream(Convert.FromBase64String(ciphertext));
		using CryptoStream stream2 = new CryptoStream(stream, transform, CryptoStreamMode.Read);
		using StreamReader streamReader = new StreamReader(stream2);
		string text3 = streamReader.ReadToEnd();
		string text4 = "encdec: decryptedData: ";
		Console.WriteLine(text4 + text3);
		return text3;
	}

	private int GetAvailableSlot()
	{
