	}

	internal Rectangle GetSlotRectangle(int slot)
	{
		Rectangle workingArea = Screen.PrimaryScreen.WorkingArea;
		int width = workingArea.Width;
		int height = workingArea.Height;
		int x = 0;
		int num = width / 4;
		switch (slot)
		{
		case 1:
			x = num * 3;
			break;
		case 2:
			x = num * 2;
			break;
		case 3:
			x = num;
			break;
		case 4:
			x = 0;
			break;
		}
		int y = workingArea.Top + (workingArea.Height - height) / 2;
		return new Rectangle(x, y, num, height);
	}

	internal Rectangle GetSlotRectangleopera(int slot)
	{
		Rectangle workingArea = Screen.PrimaryScreen.WorkingArea;
		int width = workingArea.Width;
		int height = workingArea.Height;
