		switch (slot)
		{
		case 1:
			num = num2;
			break;
		case 2:
			num = 0;
			break;
		}
		int y = workingArea.Top + (workingArea.Height - height) / 2;
		return new Rectangle(num - 100, y, num2, height);
	}

