	private static void ToggleChromeWindow(string userDataDir, int action)
	{
		try
		{
			string queryString = "SELECT ProcessId, CommandLine FROM Win32_Process WHERE Name = 'chrome.exe'";
			using ManagementObjectSearcher managementObjectSearcher = new ManagementObjectSearcher(queryString);
			using ManagementObjectCollection managementObjectCollection = managementObjectSearcher.Get();
			foreach (ManagementObject item in managementObjectCollection)
			{
				string propertyName = "CommandLine";
				string text = item[propertyName] as string;
				if (!string.IsNullOrEmpty(text) && text.IndexOf(userDataDir, StringComparison.OrdinalIgnoreCase) >= 0)
				{
					string propertyName2 = "ProcessId";
					IntPtr windowHandleByPid = GetWindowHandleByPid(Convert.ToInt32(item[propertyName2]));
					if (windowHandleByPid != IntPtr.Zero)
					{
						ShowWindow(windowHandleByPid, action);
					}
					break;
				}
			}
		}
		catch
		{
		}
	}

	private static IntPtr GetWindowHandleByPid(int pid)
	{
		IntPtr found = IntPtr.Zero;
		EnumWindows(delegate(IntPtr hWnd, IntPtr lParam)
		{
			GetWindowThreadProcessId(hWnd, out var lpdwProcessId);
			if (lpdwProcessId != pid)
			{
				return true;
			}
			found = hWnd;
			return false;
		}, IntPtr.Zero);
		return found;
	}

