	public static bool GetNetworkTime(ref DateTime dt)
	{
		dt = default(DateTime);
		bool result = false;
		try
		{
			byte[] array = new byte[48];
			array[0] = 27;
			string hostNameOrAddress = "time.google.com";
			IPEndPoint remoteEP = new IPEndPoint(Dns.GetHostEntry(hostNameOrAddress).AddressList[0], 123);
			using (Socket socket = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp))
			{
				socket.Connect(remoteEP);
				socket.ReceiveTimeout = 3000;
				socket.Send(array);
				socket.Receive(array);
				socket.Close();
			}
			long x = BitConverter.ToUInt32(array, 40);
			ulong x2 = BitConverter.ToUInt32(array, 44);
			long num = SwapEndianness((ulong)x);
			x2 = SwapEndianness(x2);
			ulong num2 = (ulong)(num * 1000) + x2 * 1000 / 4294967296L;
			DateTime dateTime = new DateTime(1900, 1, 1).AddMilliseconds((long)num2);
			string id = "India Standard Time";
			TimeZoneInfo destinationTimeZone = TimeZoneInfo.FindSystemTimeZoneById(id);
			dt = TimeZoneInfo.ConvertTimeFromUtc(dateTime, destinationTimeZone);
			result = true;
		}
		catch (Exception)
		{
		}
		return result;
	}

	private static uint SwapEndianness(ulong x)
	{
		return (uint)(((x & 0xFF) << 24) + ((x & 0xFF00) << 8) + ((x & 0xFF0000) >> 8) + ((x & 0xFF000000u) >> 24));
	}

