	internal void StartChromeNetworkCapture()
	{
		//IL_0002: Unknown result type (might be due to invalid IL or missing references)
		//IL_0008: Expected O, but got Unknown
		try
		{
			HttpClient val = new HttpClient();
			string result = val.GetStringAsync("http://localhost:9222/json").GetAwaiter().GetResult();
			JArray jArray = JArray.Parse(result);
			string text = "";
			foreach (JObject item in jArray)
			{
				if (item["type"] != null && item["type"].ToString() == "page" && item["webSocketDebuggerUrl"] != null)
				{
					text = item["webSocketDebuggerUrl"].ToString();
					break;
				}
			}
			if (!string.IsNullOrWhiteSpace(text))
			{
				ws = new WebsocketClient(new Uri(text));
				ws.MessageReceived.Subscribe(delegate(ResponseMessage msg)
				{
					ReadChromeResponse(msg.Text);
				});
				ws.Start().GetAwaiter().GetResult();
				ws.Send("{\"id\":1,\"method\":\"Network.enable\"}");
			}
		}
		catch
		{
		}
	}

	internal void ReadChromeResponse(string text)
	{
		try
		{
			if (!string.IsNullOrWhiteSpace(text))
			{
				JObject jObject = JObject.Parse(text);
				if (jObject["method"] != null && jObject["method"].ToString() == "Network.requestWillBeSent")
				{
					string text2 = jObject["params"]["request"]["url"].ToString();
					string text3 = jObject["params"]["request"]["method"].ToString();
					Console.WriteLine("===== REQUEST =====");
					Console.WriteLine("METHOD : " + text3);
					Console.WriteLine("URL    : " + text2);
				}
				if (jObject["method"] != null && jObject["method"].ToString() == "Network.responseReceived")
				{
					string text4 = jObject["params"]["requestId"].ToString();
					string text5 = jObject["params"]["response"]["url"].ToString();
					string text6 = jObject["params"]["response"]["status"].ToString();
					Console.WriteLine("===== RESPONSE =====");
					Console.WriteLine("URL    : " + text5);
					Console.WriteLine("STATUS : " + text6);
					ws.Send("{\"id\":99,\"method\":\"Network.getResponseBody\",\"params\":{\"requestId\":\"" + text4 + "\"}}");
				}
				if (jObject["id"] != null && jObject["id"].ToString() == "99" && jObject["result"] != null && jObject["result"]["body"] != null)
				{
					string text7 = jObject["result"]["body"].ToString();
				}
			}
		}
		catch
		{
		}
	}

	public void ClickSearchButton(UndetectedChromeDriver driver)
