	public void ClickSearchButtonEdge(IPage page)
	{
		string selector = "button.search_btn.train_Search[type='submit']";
		page.WaitForSelectorAsync(selector).GetAwaiter().GetResult();
		page.ClickAsync(selector).GetAwaiter().GetResult();
	}

	internal string ClassCodeToText(string code)
	{
		code = code.ToUpperInvariant().Trim();
		string result = "";
		switch (code)
		{
		case "2S":
			result = "Second Sitting (2S)";
			break;
		case "CC":
			result = "AC Chair Car (CC)";
			break;
		case "2A":
			result = "AC 2 Tier (2A)";
			break;
		case "3A":
			result = "AC 3 Tier (3A)";
			break;
		case "SL":
			result = "Sleeper (SL)";
			break;
		}
		return result;
	}

