			dictionary.Add(key, value);
			string key4 = "Accept-Language";
			string value2 = "en-US,en;q=0.9";
			dictionary.Add(key4, value2);
			string key5 = "Content-Language";
			string value3 = "en";
			dictionary.Add(key5, value3);
			string key6 = "Authorization";
			dictionary.Add(key6, _Authrization ?? "");
			string key7 = "bmiyek";
			dictionary.Add(key7, bmiyek ?? "");
			string key8 = "greq";
			dictionary.Add(key8, greq ?? "");
			string key9 = "bmirak";
			dictionary.Add(key9, bmirak ?? "");
			string key10 = "spa-csrf-token";
			dictionary.Add(key10, csrf_token ?? "");
			string key11 = "Content-Type";
			string value4 = "application/json;charset=UTF-8";
			dictionary.Add(key11, value4);
			Dictionary<string, string> headers = dictionary;
			string text = "async (args) => {\r\n            const resp = await fetch(args.url, {\r\n                method: 'POST',\r\n                headers: args.headers,\r\n                body: args.body,\r\n                credentials: 'include',\r\n                referrer: args.referer // Aapka unused parameter yahan add kar diya gaya hai\r\n            });\r\n\r\n            const text = await resp.text();\r\n\r\n            let headersReceived = {};\r\n            resp.headers.forEach((v, k) => {\r\n                headersReceived[k] = v;\r\n            });\r\n\r\n            return {\r\n                status: resp.status,\r\n                body: text,\r\n                headers: headersReceived\r\n            };\r\n        }";
			string expression = text;
			JsFetchResult jsFetchResult = await page.EvaluateAsync<JsFetchResult>(expression, new { url, headers, body, referer });
			if (jsFetchResult != null)
			{
				_response = jsFetchResult.body;
				if (jsFetchResult.headers != null)
				{
					foreach (KeyValuePair<string, string> header in jsFetchResult.headers)
					{
						string key12 = header.Key;
						string value5 = "csrf-token";
						if (key12.Equals(value5, StringComparison.OrdinalIgnoreCase))
						{
							csrf_token = header.Value;
						}
						string key13 = header.Key;
						string value6 = "spa-csrf-token";
						if (key13.Equals(value6, StringComparison.OrdinalIgnoreCase))
						{
							csrf_token = header.Value;
						}
					}
				}
				result = jsFetchResult.status >= 200 && jsFetchResult.status < 300;
			}
		}
		catch (Exception ex)
		{
			Exception ex2 = ex;
			Exception ex3 = ex2;
			string text2 = "[Playwright POST Error]: ";
			Console.WriteLine(text2 + ex3.Message);
			result = false;
		}
		return (Success: result, Response: _response);
	}

	private void ExtractCookiesFromPlaywright(IPage page, ref CookieCollection cookie_)
	{
		try
		{
			foreach (BrowserContextCookiesResult item in Task.Run(() => page.Context.CookiesAsync()).GetAwaiter().GetResult())
			{
				try
				{
					string text2;
					if (string.IsNullOrEmpty(item.Domain))
					{
						string text = ".irctc.co.in";
						text2 = text;
					}
					else
					{
						text2 = item.Domain;
					}
					string domain = text2;
					string text3;
					if (!string.IsNullOrEmpty(item.Path))
					{
						text3 = item.Path;
					}
					else
					{
						string text4 = "/";
						text3 = text4;
					}
					string path = text3;
					System.Net.Cookie cookie = new System.Net.Cookie(item.Name, item.Value)
					{
						Domain = domain,
						Path = path,
						HttpOnly = item.HttpOnly,
						Secure = item.Secure
					};
					if (item.Expires > 0f)
					{
						cookie.Expires = DateTimeOffset.FromUnixTimeSeconds((long)item.Expires).DateTime;
					}
					cookie_.Add(cookie);
				}
				catch (Exception ex)
				{
					string text5 = "[Cookie Error] ";
					string name = item.Name;
					string text6 = " skip ho gayi: ";
					Console.WriteLine(text5 + name + text6 + ex.Message);
				}
			}
			string format = "[Success] Total {0} cookies Playwright se nikal li gayi hain.";
			Console.WriteLine(string.Format(format, cookie_.Count));
		}
		catch (Exception ex2)
		{
			string text7 = "[Main Cookie Error]: ";
			Console.WriteLine(text7 + ex2.Message);
		}
	}

	public void LoadCookiesFromJsonToBrowser6666(IBrowserContext context)
	{
		string symmetricKey = "ec3104c5318c8f0753fdc13faa540020cae645c4b43f3795a0f2f9fc94328326";
		try
		{
			string encryptedInput = File.ReadAllText("Check_IP_Block_chrome");
			string value = Staticm.DecryptAES(encryptedInput, symmetricKey);
			List<Playwright_Automation.ChromeCookie> list = JsonConvert.DeserializeObject<List<Playwright_Automation.ChromeCookie>>(value);
			if (list == null || list.Count == 0)
			{
				return;
			}
			List<Microsoft.Playwright.Cookie> list2 = list.Where((Playwright_Automation.ChromeCookie c) => c != null && !string.IsNullOrWhiteSpace(c.name) && !string.IsNullOrWhiteSpace(c.value) && !string.IsNullOrWhiteSpace(c.domain)).Select(delegate(Playwright_Automation.ChromeCookie c)
			{
				Microsoft.Playwright.Cookie cookie = new Microsoft.Playwright.Cookie
				{
					Name = c.name,
					Value = c.value,
					Domain = c.domain,
					Path = (string.IsNullOrWhiteSpace(c.path) ? "/" : c.path),
					Secure = c.secure,
					HttpOnly = c.httpOnly
				};
				Microsoft.Playwright.Cookie cookie2 = cookie;
				string text = c.sameSite?.ToLower();
				if (1 == 0)
				{
				}
				SameSiteAttribute value2 = text switch
				{
					"strict" => SameSiteAttribute.Strict, 
					"lax" => SameSiteAttribute.Lax, 
					"none" => SameSiteAttribute.None, 
					"no_restriction" => SameSiteAttribute.None, 
					_ => SameSiteAttribute.Lax, 
				};
				if (1 == 0)
				{
				}
				cookie2.SameSite = value2;
				return cookie;
			}).ToList();
			context.AddCookiesAsync(list2).GetAwaiter().GetResult();
			Console.WriteLine($"Loaded {list2.Count} cookies.");
		}
		catch (Exception ex)
		{
			Console.WriteLine("[Load Cookie Error]: " + ex);
		}
	}

