	private string ToBase36(long value)
	{
		if (value == 0)
		{
			return "0";
		}
		string text = "";
		while (value > 0)
		{
			int index = (int)(value % 36);
			text = Base36Chars[index] + text;
			value /= 36;
		}
		return text;
	}

