	private string GetCookieHeader(CookieContainer handler, Uri uri)
	{
		if (handler != null && !(uri == null))
		{
			CookieCollection cookieCollection = handler.GetCookies(uri);
			if (cookieCollection == null || cookieCollection.Count == 0)
			{
				return string.Empty;
			}
			List<string> list = new List<string>(cookieCollection.Count);
			foreach (System.Net.Cookie item in cookieCollection)
			{
				string name = item.Name;
				string text = "=";
				list.Add(name + text + item.Value);
			}
			string separator = "; ";
			return string.Join(separator, list);
		}
		return string.Empty;
	}

