	public static string GetCookiesAsJson(CookieContainer handler, Uri uri)
	{
		if (handler == null)
		{
			return "{}";
		}
		CookieCollection cookieCollection = handler.GetCookies(uri);
		Dictionary<string, object> dictionary = new Dictionary<string, object>();
		foreach (System.Net.Cookie item in cookieCollection)
		{
			string name = item.Name;
			string name2 = item.Name;
			string value = item.Value;
			string domain = item.Domain;
			string path = item.Path;
			object obj;
			if (!(item.Expires == DateTime.MinValue))
			{
				DateTime expires = item.Expires;
				string text = "o";
				obj = expires.ToString(text);
			}
			else
			{
				obj = null;
			}
			dictionary[name] = new
			{
				Name = name2,
				Value = value,
				Domain = domain,
				Path = path,
				Expires = (string)obj,
				HttpOnly = item.HttpOnly,
				Secure = item.Secure
			};
		}
		return new JavaScriptSerializer().Serialize(dictionary);
	}

