		return array[random.Next(array.Length)];
	}

	private static string GenerateRandomString(int length)
	{
		if (length <= 0)
		{
			return string.Empty;
		}
		char[] array = new char[length];
		using (RandomNumberGenerator randomNumberGenerator = RandomNumberGenerator.Create())
		{
			byte[] array2 = new byte[length];
			randomNumberGenerator.GetBytes(array2);
			for (int i = 0; i < length; i++)
			{
				array[i] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"[array2[i] % "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789".Length];
			}
		}
		return new string(array);
	}

	private bool IsAdministrator()
	{
		using WindowsIdentity ntIdentity = WindowsIdentity.GetCurrent();
		WindowsPrincipal windowsPrincipal = new WindowsPrincipal(ntIdentity);
		return windowsPrincipal.IsInRole(WindowsBuiltInRole.Administrator);
	}

	private void SetRegistryValue(RegistryHive hive, string subKey, string valueName, object value, RegistryValueKind valueKind)
	{
		using RegistryKey registryKey = RegistryKey.OpenBaseKey(hive, RegistryView.Registry64);
		using RegistryKey registryKey2 = registryKey.CreateSubKey(subKey);
		if (registryKey2 == null)
		{
			throw new Exception("Registry key create/open नह\u0940\u0902 ह\u094b सक\u0940:\n" + subKey);
		}
		registryKey2.SetValue(valueName, value, valueKind);
	}

	private void ConfigureService(string serviceName, string startType)
	{
		RunCommand("sc.exe", "config \"" + serviceName + "\" start= " + startType);
	}

	private bool RunPowerShell(string command)
	{
		try
		{
			using Process process = new Process();
			process.StartInfo = new ProcessStartInfo
			{
				FileName = "powershell.exe",
				Arguments = "-NoProfile -NonInteractive -ExecutionPolicy Bypass -Command \"" + command.Replace("\"", "\\\"") + "\"",
				UseShellExecute = false,
				CreateNoWindow = true,
				WindowStyle = ProcessWindowStyle.Hidden,
				RedirectStandardOutput = true,
				RedirectStandardError = true
			};
			process.Start();
			string text = process.StandardOutput.ReadToEnd();
			string text2 = process.StandardError.ReadToEnd();
			process.WaitForExit();
			return process.ExitCode == 0;
		}
		catch
		{
			return false;
		}
	}

	private bool StopService(string serviceName)
	{
		try
		{
			using ServiceController serviceController = new ServiceController(serviceName);
			if (serviceController.Status == ServiceControllerStatus.Stopped)
			{
				return true;
			}
			if (serviceController.Status == ServiceControllerStatus.Running || serviceController.Status == ServiceControllerStatus.Paused)
			{
				serviceController.Stop();
				serviceController.WaitForStatus(ServiceControllerStatus.Stopped, TimeSpan.FromSeconds(15.0));
				return serviceController.Status == ServiceControllerStatus.Stopped;
			}
			if (serviceController.Status == ServiceControllerStatus.StopPending)
			{
				serviceController.WaitForStatus(ServiceControllerStatus.Stopped, TimeSpan.FromSeconds(15.0));
				return serviceController.Status == ServiceControllerStatus.Stopped;
			}
			return false;
		}
		catch (InvalidOperationException)
		{
			return false;
		}
		catch (Win32Exception)
		{
			return false;
		}
		catch
		{
			return false;
		}
	}

	private bool RunCommand(string fileName, string arguments)
	{
		try
		{
			using Process process = new Process();
			process.StartInfo = new ProcessStartInfo
			{
				FileName = fileName,
				Arguments = arguments,
				UseShellExecute = false,
				CreateNoWindow = true,
				WindowStyle = ProcessWindowStyle.Hidden,
				RedirectStandardOutput = true,
				RedirectStandardError = true
			};
			process.Start();
			string text = process.StandardOutput.ReadToEnd();
			string text2 = process.StandardError.ReadToEnd();
			process.WaitForExit();
			return process.ExitCode == 0;
		}
		catch
		{
			return false;
		}
	}

	private bool StartService(string serviceName)
	{
		try
		{
			using ServiceController serviceController = new ServiceController(serviceName);
			if (serviceController.Status == ServiceControllerStatus.Running)
			{
				return true;
			}
			if (serviceController.Status == ServiceControllerStatus.Stopped || serviceController.Status == ServiceControllerStatus.Paused)
			{
				serviceController.Start();
				serviceController.WaitForStatus(ServiceControllerStatus.Running, TimeSpan.FromSeconds(15.0));
				return serviceController.Status == ServiceControllerStatus.Running;
			}
			if (serviceController.Status == ServiceControllerStatus.StartPending)
			{
				serviceController.WaitForStatus(ServiceControllerStatus.Running, TimeSpan.FromSeconds(15.0));
				return serviceController.Status == ServiceControllerStatus.Running;
			}
			return false;
		}
		catch (InvalidOperationException)
		{
			return false;
		}
		catch (Win32Exception)
		{
			return false;
		}
		catch
		{
			return false;
		}
	}

	private void EnableLocationAndIPv6()
	{
		try
		{
			if (!IsAdministrator())
			{
				MessageBox.Show("Administrator permission required.\n\nPlease run the application as Administrator.", "Administrator Required", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				return;
			}
			SetRegistryValue(RegistryHive.LocalMachine, "SOFTWARE\\Policies\\Microsoft\\Windows\\LocationAndSensors", "DisableLocation", 0, RegistryValueKind.DWord);
			SetRegistryValue(RegistryHive.LocalMachine, "SOFTWARE\\Policies\\Microsoft\\Windows\\LocationAndSensors", "DisableSensors", 0, RegistryValueKind.DWord);
			SetRegistryValue(RegistryHive.LocalMachine, "SOFTWARE\\Policies\\Microsoft\\Windows\\LocationAndSensors", "DisableLocationScripting", 0, RegistryValueKind.DWord);
			SetRegistryValue(RegistryHive.LocalMachine, "SOFTWARE\\Policies\\Microsoft\\Windows\\AppPrivacy", "LetAppsAccessLocation", 0, RegistryValueKind.DWord);
			SetRegistryValue(RegistryHive.LocalMachine, "SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\CapabilityAccessManager\\ConsentStore\\location", "Value", "Allow", RegistryValueKind.String);
			SetRegistryValue(RegistryHive.CurrentUser, "SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\CapabilityAccessManager\\ConsentStore\\location", "Value", "Allow", RegistryValueKind.String);
			ConfigureService("lfsvc", "auto");
			StartService("lfsvc");
			ConfigureService("SensorService", "demand");
			StartService("SensorService");
			ConfigureService("SensrSvc", "demand");
			StartService("SensrSvc");
			ConfigureService("SensorDataService", "demand");
			StartService("SensorDataService");
			SetRegistryValue(RegistryHive.LocalMachine, "SYSTEM\\CurrentControlSet\\Services\\Tcpip6\\Parameters", "DisabledComponents", 0, RegistryValueKind.DWord);
			RunCommand("netsh", "interface teredo set state default");
			RunCommand("netsh", "interface ipv6 6to4 set state default");
			RunCommand("netsh", "interface ipv6 isatap set state default");
			string command = "Get-NetAdapterBinding -ComponentID ms_tcpip6 -ErrorAction SilentlyContinue | Where-Object {$_.Enabled -eq $false} | Enable-NetAdapterBinding -ComponentID ms_tcpip6 -Confirm:$false -ErrorAction SilentlyContinue";
			RunPowerShell(command);
			RunCommand("ipconfig", "/flushdns");
			string path = Path.Combine(Application.StartupPath, "setting.dll");
			if (File.Exists(path))
			{
				File.Delete(path);
			}
			File.WriteAllText(path, "OK");
			Process.Start(new ProcessStartInfo
			{
				FileName = "shutdown.exe",
				Arguments = "/r /t 0",
				UseShellExecute = true,
				Verb = "runas"
			});
		}
		catch (Exception)
		{
		}
	}

	private void DisableLocationAndIPv6()
	{
		try
		{
			if (!IsAdministrator())
			{
				MessageBox.Show("Administrator permission is required.\n\nPlease run the application as Administrator.", "Administrator Required", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				return;
			}
			SetRegistryValue(RegistryHive.LocalMachine, "SOFTWARE\\Policies\\Microsoft\\Windows\\LocationAndSensors", "DisableLocation", 1, RegistryValueKind.DWord);
			SetRegistryValue(RegistryHive.LocalMachine, "SOFTWARE\\Policies\\Microsoft\\Windows\\LocationAndSensors", "DisableSensors", 1, RegistryValueKind.DWord);
			SetRegistryValue(RegistryHive.LocalMachine, "SOFTWARE\\Policies\\Microsoft\\Windows\\LocationAndSensors", "DisableLocationScripting", 1, RegistryValueKind.DWord);
			SetRegistryValue(RegistryHive.LocalMachine, "SOFTWARE\\Policies\\Microsoft\\Windows\\AppPrivacy", "LetAppsAccessLocation", 2, RegistryValueKind.DWord);
			SetRegistryValue(RegistryHive.LocalMachine, "SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\CapabilityAccessManager\\ConsentStore\\location", "Value", "Deny", RegistryValueKind.String);
