				string text = "Found _abck cookie with value: ";
				Console.WriteLine(text + cookie.Value);
				return true;
			}
		}
		return false;
	}

	public string ReplaceAbckInCookieString(string originalCookieString, string newAbckValue)
	{
		List<string> list = (from part in originalCookieString.Split(';')
			select part.Trim()).Where(delegate(string part)
		{
			string value = "_abck=";
			return !part.StartsWith(value, StringComparison.OrdinalIgnoreCase);
		}).ToList();
		string text = "_abck=";
		list.Add(text + newAbckValue);
		string separator = "; ";
		return string.Join(separator, list);
	}

