	private string GetRandomLinesFromFile(string filePath)
	{
		if (File.Exists(filePath))
		{
			string[] array = (from line in File.ReadAllLines(filePath)
				where !string.IsNullOrWhiteSpace(line)
				select line.Trim()).Where(delegate(string line)
			{
				string value = "&4.1.3";
				return line.EndsWith(value, StringComparison.Ordinal);
			}).ToArray();
			if (array.Length == 0)
			{
				return "";
			}
			return array[new Random().Next(array.Length)];
		}
		return "";
	}

