	private static string ProxyToString(WebProxy proxy)
	{
		if (proxy == null || proxy.Address == null)
		{
			return string.Empty;
		}
		string text = proxy.Address.ToString().TrimEnd('/');
		if (!(proxy.Credentials is NetworkCredential networkCredential))
		{
			return text;
		}
		string[] array = new string[6];
		string text2 = "http://";
		array[0] = text2;
		array[1] = networkCredential.UserName;
		string text3 = ":";
		array[2] = text3;
		array[3] = networkCredential.Password;
		string text4 = "@";
		array[4] = text4;
		string oldValue = "http://";
		string text5 = text.Replace(oldValue, "");
		string oldValue2 = "https://";
		array[5] = text5.Replace(oldValue2, "");
		return string.Concat(array);
	}

