			sslStream.AuthenticateAsClient(host, null, SslProtocols.Tls12, checkCertificateRevocation: true);
			string value2 = "SslStream Authenticated.";
			Console.WriteLine(value2);
			string text = "SslProtocol: ";
			Console.WriteLine(text + sslStream.SslProtocol);
			string text2 = "CipherAlgorithm: ";
			string text3 = sslStream.CipherAlgorithm.ToString();
			string text4 = " Strength: ";
			Console.WriteLine(text2 + text3 + text4 + sslStream.CipherStrength);
			string text5 = "HashAlgorithm: ";
			string text6 = sslStream.HashAlgorithm.ToString();
			string text7 = " Strength: ";
			Console.WriteLine(text5 + text6 + text7 + sslStream.HashStrength);
			string text8 = "KeyExchangeAlgorithm: ";
			string text9 = sslStream.KeyExchangeAlgorithm.ToString();
			string text10 = " Strength: ";
			Console.WriteLine(text8 + text9 + text10 + sslStream.KeyExchangeStrength);
			X509Certificate remoteCertificate = sslStream.RemoteCertificate;
			if (remoteCertificate == null)
