	private static void PrintCertificateInfo(X509Certificate cert)
	{
		if (cert == null)
		{
			string value = "Certificate: NULL";
			Console.WriteLine(value);
			return;
		}
		try
		{
			X509Certificate2 x509Certificate = new X509Certificate2(cert);
			string text = "  Subject: ";
			Console.WriteLine(text + x509Certificate.Subject);
			string text2 = "  Issuer: ";
			Console.WriteLine(text2 + x509Certificate.Issuer);
			string text3 = "  Thumbprint: ";
			Console.WriteLine(text3 + x509Certificate.Thumbprint);
			string text4 = "  NotBefore: ";
			Console.WriteLine(text4 + x509Certificate.NotBefore.ToString());
			string text5 = "  NotAfter: ";
			Console.WriteLine(text5 + x509Certificate.NotAfter.ToString());
			string text6 = "  SerialNumber: ";
			Console.WriteLine(text6 + x509Certificate.SerialNumber);
			string[] array = new string[5];
			string text7 = "  FriendlyName: ";
			array[0] = text7;
			array[1] = x509Certificate.PublicKey.Oid.FriendlyName;
			string text8 = " (";
			array[2] = text8;
			array[3] = x509Certificate.PublicKey.Oid.Value;
			string text9 = ")";
			array[4] = text9;
			Console.WriteLine(string.Concat(array));
		}
		catch (Exception ex)
		{
			string text10 = "  (error printing cert details) ";
			Console.WriteLine(text10 + ex.Message);
		}
	}

	private static void PrintChainInfo(X509Chain chain)
	{
		if (chain == null)
		{
			string value = "Chain: NULL";
			Console.WriteLine(value);
			return;
		}
		string text = "Chain.ChainElements.Count = ";
		Console.WriteLine(text + chain.ChainElements.Count);
		for (int i = 0; i < chain.ChainElements.Count; i++)
		{
			X509ChainElement x509ChainElement = chain.ChainElements[i];
			string format = "  Element[{0}]: Subject={1}, Issuer={2}, Thumb={3}";
			Console.WriteLine(string.Format(format, i, x509ChainElement.Certificate.Subject, x509ChainElement.Certificate.Issuer, x509ChainElement.Certificate.Thumbprint));
			if (x509ChainElement.ChainElementStatus != null && x509ChainElement.ChainElementStatus.Length != 0)
			{
				X509ChainStatus[] chainElementStatus = x509ChainElement.ChainElementStatus;
				for (int j = 0; j < chainElementStatus.Length; j++)
				{
					X509ChainStatus x509ChainStatus = chainElementStatus[j];
					string format2 = "    Status: {0} - {1}";
					Console.WriteLine(string.Format(format2, x509ChainStatus.Status, x509ChainStatus.StatusInformation));
				}
			}
		}
	}

